package com.example.smartpantry.ui;

import android.app.*;import android.os.*;import android.content.*;import android.graphics.Color;import android.view.*;import android.widget.*;import com.example.smartpantry.data.PantryDbHelper;import com.example.smartpantry.model.Models.Recipe;import java.util.*;

public class SuggestedRecipesActivity extends Activity { PantryDbHelper db; LinearLayout root; ListView list; ArrayList<Recipe> matches;
 public void onCreate(Bundle b){super.onCreate(b);db=new PantryDbHelper(this);build();} protected void onResume(){super.onResume();if(db!=null)load();}
 void build(){root=Ui.page(this);root.addView(Ui.title(this,"Suggested recipes"));TextView sub=Ui.label(this,"Only recipes you can make right now are shown.");sub.setTextColor(Ui.green);root.addView(sub);list=new ListView(this);list.setDivider(null);root.addView(list,new LinearLayout.LayoutParams(-1,0,1));root.addView(Ui.nav(this,v->startActivity(new Intent(this,MainActivity.class)),v->{},v->startActivity(new Intent(this,SettingsActivity.class))));setContentView(root);}
 void load(){matches=new ArrayList<>(db.getStrictMatches());list.setAdapter(new BaseAdapter(){public int getCount(){return matches.size();}public Object getItem(int p){return matches.get(p);}public long getItemId(int p){return matches.get(p).id;}public View getView(int p,View v,ViewGroup g){Recipe r=matches.get(p);TextView t=new TextView(SuggestedRecipesActivity.this);t.setText(r.name+"\n"+r.ingredients.size()+" ingredients · Ready to cook");t.setTextSize(17);t.setTextColor(Ui.text);t.setPadding(24,18,24,18);t.setBackground(Ui.round(Color.WHITE,18));t.setOnClickListener(x->{Intent i=new Intent(SuggestedRecipesActivity.this,RecipeDetailActivity.class);i.putExtra("recipeId",r.id);startActivity(i);});LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,82);lp.setMargins(16,6,16,6);t.setLayoutParams(lp);return t;}});if(matches.isEmpty())list.setEmptyView(Ui.empty(this,"No recipes match your pantry yet.\nAdd more ingredients to see what you can cook."));}
}
